import{_ as c,C as t,o as g,c as h,j as r,a as s,G as e,a2 as i}from"./chunks/framework.BgSoyxN5.js";const C=JSON.parse('{"title":"Партнерство TickerForge в Telegram | Вердикт по акции, инсайдеры, фонды и идеи","description":"TickerForge как исследовательский слой для финансовых Telegram-каналов: проверки по компании, регулярные идеи по акциям, готовые партнерские посты, отслеживаемые ссылки в бота и измеримые пилоты.","frontmatter":{"title":"Партнерство TickerForge в Telegram | Вердикт по акции, инсайдеры, фонды и идеи","description":"TickerForge как исследовательский слой для финансовых Telegram-каналов: проверки по компании, регулярные идеи по акциям, готовые партнерские посты, отслеживаемые ссылки в бота и измеримые пилоты.","aside":false,"locale":"ru","alternateLocales":{"en":"/partners/stock-analysis-and-ideas","ru":"/ru/partners/stock-analysis-and-ideas"},"pageClass":"partners-page"},"headers":[],"relativePath":"ru/partners/stock-analysis-and-ideas.md","filePath":"ru/partners/stock-analysis-and-ideas.md","lastUpdated":1788410450000}'),m={name:"ru/partners/stock-analysis-and-ideas.md"},u={class:"partners-wide"},f={class:"partners-post-gallery"},v={class:"partners-wide"};function k(b,a,_,T,P,q){const l=t("PartnerPageAnalytics"),o=t("PartnerChannelCta"),n=t("PartnerPostImage"),p=t("PartnerCabinetCta"),d=t("PartnerLeadForm");return g(),h("div",null,[a[0]||(a[0]=r("h1",{id:"партнерство-анализ-акции-и-идеи",tabindex:"-1"},[s("Партнёрство: анализ акций и идеи "),r("a",{class:"header-anchor",href:"#партнерство-анализ-акции-и-идеи","aria-label":'Permalink to "Партнёрство: анализ акций и идеи"'},"​")],-1)),a[1]||(a[1]=r("p",null,"Анализ компаний, который ваш канал может публиковать: разбор тикера, контекст по инсайдерам и фондам, регулярные идеи по акциям — с отслеживаемыми ссылками обратно в TickerForge.",-1)),a[2]||(a[2]=r("p",null,[s("Это направление только про акции и компании. Рыночная и макро-программа живет на странице "),r("a",{href:"/ru/partners/market-news"},"Рыночные новости"),s(", а диагностика портфеля — на странице "),r("a",{href:"/ru/partners/portfolio-health"},"Здоровье портфеля"),s(".")],-1)),e(l,{offer:"telegram_research",locale:"ru"}),a[3]||(a[3]=r("div",{class:"partners-hero-actions"},[r("a",{class:"partners-button partners-button--primary",href:"#partner-contact","data-partner-event":"cta","data-partner-option":"propose_pilot","data-analytics-placement":"partner_hero"},"Предложить пилот"),r("a",{class:"partners-button partners-button--secondary",href:"#research-formats","data-partner-event":"cta","data-partner-option":"see_formats","data-analytics-placement":"partner_hero"},"Посмотреть форматы")],-1)),e(o,{eyebrow:"Посмотрите вживую",title:"Исследовательские посты в живом канале",text:"В публичном канале TickerForge выходят такие же блоки с данными, какие партнер может использовать в своих публикациях. Откройте канал перед выбором формата пилота.",cta:"Открыть канал TickerForge"}),a[4]||(a[4]=i('<p class="partners-locale-switch"><a href="/partners/stock-analysis-and-ideas" hreflang="en" data-partner-event="cta" data-partner-option="locale_en" data-analytics-placement="partner_locale_switch">Read this page in English</a></p><p class="partners-backlink">Это одно из трех направлений партнерства. <a href="/ru/partners">Все варианты партнерства</a> · <a href="/ru/partners/market-news">Рыночные новости</a> · <a href="/ru/partners/portfolio-health">Здоровье портфеля</a> · <a href="/ru/partners/requirements">Требования к партнерам</a></p><p>TickerForge - образовательное ПО для поддержки решений. Это не инвестиционная рекомендация, не сигнальный канал, не брокер и не обещание доходности.</p><h2 id="что-это-такое" tabindex="-1">Что это такое <a class="header-anchor" href="#что-это-такое" aria-label="Permalink to &quot;Что это такое&quot;">​</a></h2><p>Исследовательский слой для постов, которые вы и так хотите писать. Ваш голос и ваш вывод остаются вашими; TickerForge дает под ними блок с данными и отслеживаемую ссылку для читателей, которые захотят проверить компанию сами.</p><div class="partners-wide partners-wide--cards"><div class="partners-card"><span>По тикеру</span><strong>Проверить компанию, о которой пишете.</strong><p>Качество бизнеса, оценочный контекст, владельцы капитала, инсайдеры, тайминг и риск по одному символу.</p></div><div class="partners-card"><span>Регулярно</span><strong>Идеи, которые задают ритм каналу.</strong><p>Форматы, которые сами выбирают компании каждую неделю, - у канала есть что публиковать без поиска темы.</p></div><div class="partners-card"><span>Измеримо</span><strong>У каждого поста своя отслеживаемая ссылка.</strong><p>Клики, старты бота и реферальная привязка видны в Partner Cabinet.</p></div></div><h2 id="research-formats" tabindex="-1">Форматы анализа и идей <a class="header-anchor" href="#research-formats" aria-label="Permalink to &quot;Форматы анализа и идей {#research-formats}&quot;">​</a></h2><p>Два типа контента. Одобренный партнер создает форматы, которые Partner Cabinet поддерживает сегодня; остальные из списка можно запросить как формат пилота.</p><h3 id="на-чем-построен-пост-с-анализом-акции" tabindex="-1">На чём построен пост с анализом акции <a class="header-anchor" href="#на-чем-построен-пост-с-анализом-акции" aria-label="Permalink to &quot;На чём построен пост с анализом акции&quot;">​</a></h3><p>Партнёрский пост — это не заголовок с тикером. Каждый собирается из того же слоя, на котором работает сам продукт, и именно этого читатель не получит из скриншота графика.</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>60+ финансовых показателей на период, год и квартал.</strong> Выручка, маржинальность, денежный поток, долг, покрытие, отдача — по каждой компании и по каждому году и кварталу, что у нас есть. Изменение таким образом измеряется, а не утверждается.</li><li><strong>Сжато в один экран и раскрашено.</strong> Ценность не в том, что данные есть, а в том, что читатель видит движение год к году и квартал к кварталу, фундаментальные риски и место, где рост сменил направление, — не открывая отчётность.</li><li><strong>Детект разворота (turnaround).</strong> Начали ли квартальные цифры двигаться в обратную сторону после полосы спада — как стадия, а не как мнение.</li><li><strong>Числовой рейтинг TickerForge и его собственный 5-летний тренд.</strong> Рейтинг сравнивается со своей же 5-летней скользящей: видно, оценена компания лучше или хуже собственной истории, а не только где она стоит сегодня.</li><li><strong>Институциональные держатели по 37 отслеживаемым фондам.</strong> Не «фонд купил», а статистика по конкретной акции в фиксированном именованном наборе из 37 фондов — поэтому ответ сравним между компаниями и между кварталами.</li><li><strong>Инсайдеры — NET за 3 и 12 месяцев.</strong> Не одна заметная покупка, а покупки минус продажи по двум окнам, от людей, обязанных декларировать каждую сделку.</li></ul></div><p>Именно поэтому на это можно быстро реагировать: работа по сборке уже сделана, и аудитория видит вывод вместе с доказательствами.</p><h3 id="анализ-акции" tabindex="-1">Анализ акций <a class="header-anchor" href="#анализ-акции" aria-label="Permalink to &quot;Анализ акций&quot;">​</a></h3><div class="partners-wide"><div class="partners-format-grid"><div class="partners-format"><span>Доступно в Partner Cabinet</span><strong>Вердикт по акции</strong><p>Блок по одному тикеру: качество, оценочный контекст, владельцы капитала, тайминг и риск.</p></div><div class="partners-format"><span>Доступно в Partner Cabinet</span><strong>Активность инсайдеров</strong><p>Открытые покупки и продажи инсайдеров по тикеру. Это данные, а не вывод за читателя.</p></div><div class="partners-format"><span>Доступно в Partner Cabinet</span><strong>Движения фондов</strong><p>Институциональная поддержка и потоки фондов по доступной отчетности.</p></div></div></div><h3 id="идеи-по-акциям" tabindex="-1">Идеи по акциям <a class="header-anchor" href="#идеи-по-акциям" aria-label="Permalink to &quot;Идеи по акциям&quot;">​</a></h3><p>Идея здесь — это результат фильтра с приложенным обоснованием, а не имя, которое кому-то понравилось. Каждый формат — фиксированное правило, которое компания либо проходит, либо нет, прогнанное по тем же 60+ показателям, слою из 37 фондов и инсайдерским NET-окнам выше.</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Правило фиксировано и названо.</strong> Каждый формат проверяет одну конкретную вещь и говорит, какую. С правилом можно спорить — с «подборкой» спорить не о чем.</li><li><strong>Доказательства едут вместе с идеей.</strong> В посте есть те самые цифры, по которым компания прошла отбор: аудиторию не просят верить шортлисту на слово.</li><li><strong>Каждый формат называет, чего он НЕ проверяет.</strong> Формат разворота не смотрит на оценку, инсайдерский — на бизнес. Именно это удерживает идею от того, чтобы читаться как рекомендация.</li><li><strong>Одна идея на формат в неделю зарезервирована за вами</strong> — два партнёра никогда не опубликуют одну компанию на одной неделе.</li></ul></div><div class="partners-wide"><div class="partners-format-grid"><div class="partners-format"><span>Доступно в Partner Cabinet</span><strong>Разворот (Turnaround)</strong><p>Компания, у которой квартальные показатели пошли вверх после периода спада. Это ранние признаки восстановления, а не само восстановление.</p></div><div class="partners-format"><span>Доступно в Partner Cabinet</span><strong>Инсайдеры покупают</strong><p>Заметные чистые покупки инсайдеров за последние месяцы - от людей, которые отчитываются по каждой сделке.</p></div><div class="partners-format"><span>Доступно для пилотов</span><strong>Triple Rated</strong><p>Компании, где сразу несколько рейтинговых слоев TickerForge сходятся достаточно сильно, чтобы посмотреть внимательнее.</p></div><div class="partners-format"><span>Доступно для пилотов</span><strong>Watchlist накопления</strong><p>Тематические подборки - крупные компании, инфраструктура эпохи AI, дивидендные истории - из скана накопления.</p></div><div class="partners-format"><span>Доступно для пилотов</span><strong>Weekly Gems</strong><p>Формат «незаметных» идей из исследовательского конвейера по акциям.</p></div></div></div><p>Выберите нужные форматы в форме внизу страницы. Форматы с пометкой «доступно для пилотов» готовятся вместе с нами, а не одним нажатием в кабинете, и спрос партнеров определяет, что станет self-serve следующим.</p><div class="partners-wide partners-routing-note"><p><strong>Каждый формат идей — подробно.</strong> Что проверяет, чего намеренно не проверяет, как компания проходит отбор и как выглядит опубликованная карточка. Одна страница, девять форматов.</p><a class="partners-button partners-button--primary" href="/stock-ideas" data-partner-event="cta" data-partner-option="stock_ideas" data-analytics-placement="partner_ideas_banner">Открыть все девять форматов идей</a></div><h2 id="примеры-партнерских-постов-в-telegram" tabindex="-1">Примеры партнёрских постов в Telegram <a class="header-anchor" href="#примеры-партнерских-постов-в-telegram" aria-label="Permalink to &quot;Примеры партнёрских постов в Telegram&quot;">​</a></h2>',21)),r("div",u,[r("div",f,[e(n,{src:"/partners/examples/stock-research-sample.png",alt:"Пример партнерского поста TickerForge: вердикт по акции с качеством бизнеса, фондами, таймингом и ссылкой в бот",caption:"Вердикт по акции - так его публикует партнер.","zoom-label":"Открыть пример поста в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"}),e(n,{src:"/partners/examples/turnaround-detected-sample.png",alt:"Пример партнерского поста TickerForge: разворот со стадией восстановления и скором",caption:"Разворот - со скором и стадией восстановления.","zoom-label":"Открыть пример поста в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"}),e(n,{src:"/partners/examples/insider-buying-sample.png",alt:"Пример партнерского поста TickerForge: инсайдеры покупают, с контекстом чистых покупок",caption:"Инсайдеры покупают - с объемом и характером покупок.","zoom-label":"Открыть пример поста в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"})])]),e(p,{locale:"ru"}),a[5]||(a[5]=i('<h2 id="как-проходит-пилот-по-анализу-и-идеям" tabindex="-1">Как проходит пилот по анализу и идеям <a class="header-anchor" href="#как-проходит-пилот-по-анализу-и-идеям" aria-label="Permalink to &quot;Как проходит пилот по анализу и идеям&quot;">​</a></h2><div class="partners-wide partners-wide--timeline"><div class="partners-steps"><div><span>1</span><strong>Назвать формат</strong><p>В форме ниже выберите направление «Анализ акций и идеи» и форматы, которые действительно будет читать ваша аудитория.</p></div><div><span>2</span><strong>Получить партнерский доступ</strong><p>Одобренный партнер получает Standard на срок пилота, и в Telegram открывается Partner Cabinet.</p></div><div><span>3</span><strong>Сделать пост</strong><p>Сгенерировать поддерживаемый формат в кабинете или получить подготовленный пост для формата, который пока запрашивается пилотом.</p></div><div><span>4</span><strong>Опубликовать своим голосом</strong><p>Ваш анализ остается вашим; добавляются блок TickerForge, дисклеймер и ваша отслеживаемая ссылка.</p></div><div><span>5</span><strong>Измерить и решить</strong><p>Статистика в кабинете показывает результат постов; дальше вы решаете - продолжать, менять формат или остановиться.</p></div></div></div><h2 id="measurement" tabindex="-1">Как считается результат <a class="header-anchor" href="#measurement" aria-label="Permalink to &quot;Как считается результат {#measurement}&quot;">​</a></h2><p>Каждый сгенерированный пост получает короткую отслеживаемую ссылку. Сама ссылка непрозрачна — в ней не зашиты код партнёра, месяц, формат, сценарий или тикер: эти значения хранятся отдельно, как поля отчёта.</p><p>В Partner Cabinet сейчас доступны:</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Statistics:</strong> суммарные tracked clicks, рефералы, paid referrals текущего месяца и короткая разбивка по типам постов за текущий месяц.</li><li><strong>Monthly Report:</strong> XLSX за текущий или предыдущий месяц с листами Summary и Posts.</li><li><strong>Raw clicks:</strong> переходы по ссылке, не уникальные люди.</li><li><strong>Bot starts:</strong> уникальные Telegram-пользователи, чей первый partner-post старт пришел из конкретного поста.</li><li><strong>New referrals:</strong> пользователи, которых существующая Ambassador-модель впервые привязала к партнеру после такого старта.</li><li><strong>Paid subscriptions:</strong> текущий снимок активных paid-подписок среди таких рефералов, а не исторический платежный ledger.</li></ul></div><h2 id="что-получает-партнер" tabindex="-1">Что получает партнёр <a class="header-anchor" href="#что-получает-партнер" aria-label="Permalink to &quot;Что получает партнёр&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li>Готовые посты с исследованием компании — генерируются по запросу, а не пишутся.</li><li>Еженедельные идеи по акциям с приложенными доказательствами отбора.</li><li>Картинка и форматирование канала — пост можно переслать как есть.</li><li>Отслеживаемые ссылки внутри каждого формата.</li><li>Посты на английском или русском — переключается в кабинете.</li><li>Статистика по типам постов и месячный отчёт в XLSX.</li><li>Одна идея на формат в неделю зарезервирована за вами — двум партнёрам не выдадут одну компанию.</li><li>Разговор про API или собственный фид, если пилот сработал.</li></ul></div><p>Условия участия, обязательства по публикациям и правила доступа одинаковы для всех направлений и живут на странице <a href="/ru/partners/requirements">требований к партнёрам</a>.</p><h2 id="кому-подходит" tabindex="-1">Кому подходит <a class="header-anchor" href="#кому-подходит" aria-label="Permalink to &quot;Кому подходит&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li>Telegram-каналам и инвестиционным сообществам, которые разбирают отдельные компании.</li><li>Авторам в Instagram и TikTok, которым нужна защищаемая карточка акции, а не очередное мнение.</li><li>YouTube-каналам, которые начинают с компании и хотят иметь цифры до съёмки.</li><li>Авторам в LinkedIn, публикующим разбор компаний для профессиональной аудитории.</li><li>Рассылкам и Discord-группам с регулярной рубрикой идей.</li><li>Всем, кто хочет говорить о компании, не проводя вечер в её отчётности.</li></ul></div><h2 id="partner-access" tabindex="-1">Модель партнерского доступа <a class="header-anchor" href="#partner-access" aria-label="Permalink to &quot;Модель партнерского доступа {#partner-access}&quot;">​</a></h2><p>Первый пилот включает временный creator access.</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Что получает партнер:</strong> доступ уровня Standard на срок пилота, обычно 30 дней, плюс готовые research-блоки, tracked links, реферальную атрибуцию и статистику в кабинете.</li><li><strong>Что нужно сделать:</strong> 3 качественных Telegram-поста за пилот, затем 2-4 в месяц, если пилот продолжается.</li><li><strong>Кому подходит:</strong> финансовые каналы примерно от 1 000 реальных подписчиков; меньшие, но активные сообщества рассматриваются отдельно.</li><li><strong>Что считается качественным постом:</strong> реальный блок TickerForge, собственный анализ автора, образовательный disclaimer и tracked link.</li><li><strong>Если ритм остановился:</strong> complimentary access ставится на паузу и возвращается к обычному free-уровню.</li></ul></div><p>Полные условия участия и точные причины, по которым доступ заканчивается, - на странице <a href="/ru/partners/requirements">требований к партнерам</a>.</p><h2 id="чем-tickerforge-не-является" tabindex="-1">Чем TickerForge не является <a class="header-anchor" href="#чем-tickerforge-не-является" aria-label="Permalink to &quot;Чем TickerForge не является&quot;">​</a></h2><div class="partners-wide partners-routing-note"><p>TickerForge - это не:</p><ul class="partners-feature-list"><li>сигнальный канал</li><li>торговый бот</li><li>брокер</li><li>личная инвестиционная рекомендация</li><li>обещание доходности</li><li>автоматическая финансовая консультация</li></ul><p>TickerForge - образовательное ПО для поддержки решений: оно помогает смотреть на бизнес, оценку, владельцев капитала и рыночный контекст до публикации.</p></div><h2 id="partner-contact" tabindex="-1">Запросить формат анализа или идей <a class="header-anchor" href="#partner-contact" aria-label="Permalink to &quot;Запросить формат анализа или идей {#partner-contact}&quot;">​</a></h2><p>Опишите ваш канал, аудиторию и форматы, которые хотите видеть первыми. Полезные детали: ссылка на канал, размер аудитории, язык, основная тема, частота постов и первые идеи по тикерам.</p>',19)),r("div",v,[e(d,{locale:"ru",source:"partners_telegram_research","default-program":"TELEGRAM_RESEARCH"})]),a[6]||(a[6]=i('<h2 id="полезные-ссылки" tabindex="-1">Полезные ссылки <a class="header-anchor" href="#полезные-ссылки" aria-label="Permalink to &quot;Полезные ссылки&quot;">​</a></h2><ul><li><a href="/ru/partners">Все варианты партнерства</a></li><li><a href="/ru/partners/cabinet">Как работает Partner Cabinet</a></li><li><a href="/ru/partners/requirements">Требования к партнерам</a></li><li><a href="/ru/partners/market-news">Рыночные новости</a></li><li><a href="/ru/partners/portfolio-health">Здоровье портфеля</a></li><li><a href="/stock-widget">Проверка отдельной акции</a></li><li><a href="/market-widget">Рыночный виджет</a></li><li><a href="/ambassador">Амбассадорская программа</a></li></ul>',2))])}const x=c(m,[["render",k]]);export{C as __pageData,x as default};
